-- ============================================================
-- 完形批1: 7B U1+U2 共4篇(各8空); 解析精简加粗; 答案已打散(ABCD各2)
-- 含修复:U1第2篇(7)→can; U2第2篇(7)→for(原take/bring软判断已删)
-- 幂等 WHERE NOT EXISTS by title; ⚠️先跑过 cloze-step1-ddl.sql 建表
-- ============================================================

INSERT INTO junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order)
SELECT 'c1000001-0a1b-4c2d-8e3f-000000000001', 7, '7B', 'U1', '七下 U1 完形:Pandas at the Zoo', 'Hello! I am a guide at the zoo. Let me show you my favorite animals. Look at these (1)____! They are pandas. They come from China. They are black and (2)____, and they look very cute. Now, look at the baby panda. It (3)____ on the grass. It is very small. What (4)____ the mother panda do? She (5)____ a lot of bamboo every day. Pandas like bamboo very much. The father panda is under the tree. He sleeps (6)____ daytime. There (7)____ many people here today. They all like the pandas. Do you want to take a photo (8)____ them?', 101, 2, '[{"q":"1","options":["animal","animals","tiger","tigers"],"answer":"B","explanation":"后文 They are pandas(复数)→可数名词复数 **animals**。"},{"q":"2","options":["white","yellow","brown","blue"],"answer":"A","explanation":"熊猫黑白相间→black and **white**(常识)。"},{"q":"3","options":["play","playing","played","plays"],"answer":"D","explanation":"It 是第三人称单数,一般现在时动词加 s→**plays**。"},{"q":"4","options":["do","is","does","are"],"answer":"C","explanation":"主语 the mother panda 单三,疑问句用 **does**+动词原形。"},{"q":"5","options":["eats","eat","eating","to eat"],"answer":"A","explanation":"She 单三→一般现在时动词加 s→**eats**。"},{"q":"6","options":["on","at","in","from"],"answer":"C","explanation":"在白天用 **in** the daytime。"},{"q":"7","options":["is","are","am","be"],"answer":"B","explanation":"there be + many people(复数)→there **are**。"},{"q":"8","options":["for","in","on","with"],"answer":"D","explanation":"take a photo **with** sb=和某人合影。"}]'::jsonb, 1
WHERE NOT EXISTS (SELECT 1 FROM junior_cloze WHERE title = '七下 U1 完形:Pandas at the Zoo');

INSERT INTO junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order)
SELECT 'c1000002-0a1b-4c2d-8e3f-000000000002', 7, '7B', 'U1', '七下 U1 完形:Elephant Friends', 'I have a story about some special friends. They are elephants. Elephants are very (1)____, but they are friendly to people. Look! These elephants have long (2)____ and large ears. They also have a very long (3)____ to help them eat and drink. They are from Africa. They (4)____ in the forest. What do they like to eat? They love plants, fruit and (5)____. They can eat a lot every day! Elephants are also very (6)____. They can help people work, and they can play games. They walk very slowly, but they (7)____ swim well in the river. Do you (8)____ these amazing animal friends? Please come and see them.', 110, 2, '[{"q":"1","options":["small","dangerous","big","beautiful"],"answer":"C","explanation":"大象体型 **big**,后接 but 转折(但对人友好)。"},{"q":"2","options":["arms","legs","hair","hands"],"answer":"B","explanation":"大象有粗壮的长 **legs**(腿),不是 arms/hands。"},{"q":"3","options":["nose","tail","neck","head"],"answer":"A","explanation":"大象用长 **nose**(鼻子)吃喝,最标志特征。"},{"q":"4","options":["sleep","run","fly","live"],"answer":"D","explanation":"**live** in the forest=生活在森林。"},{"q":"5","options":["meat","vegetables","fish","milk"],"answer":"B","explanation":"草食:plants、fruit 和 **vegetables**(蔬菜)。"},{"q":"6","options":["lazy","scary","ugly","clever"],"answer":"D","explanation":"能帮人工作、会玩游戏→很 **clever**(聪明)。"},{"q":"7","options":["can","do","are","like"],"answer":"A","explanation":"they **can** swim well(can 表能力,后接动词原形)。"},{"q":"8","options":["call","see","like","make"],"answer":"C","explanation":"Do you **like** these animal friends?(喜欢)"}]'::jsonb, 2
WHERE NOT EXISTS (SELECT 1 FROM junior_cloze WHERE title = '七下 U1 完形:Elephant Friends');

INSERT INTO junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order)
SELECT 'c2000001-0a1b-4c2d-8e3f-000000000003', 7, '7B', 'U2', '七下 U2 完形:Our School Rules', 'Rules are everywhere. At our school, we have many rules and we must follow (1)____ every day. First, we cannot be late (2)____ school. We must arrive at the classroom before 7:30 a.m. Second, we must wear our school (3)____ from Monday to Friday. Can we (4)____ food into the classroom? No, we can''t. We can only eat in the dining hall. Third, look at the signs in the hallway. They say, "(5)____ run here!" and "Be quiet." We must (6)____ quietly in the hallway. Rules help us study well. Do you (7)____ to follow rules at your school? Let (8)____ be good students together.', 105, 2, '[{"q":"1","options":["them","it","they","him"],"answer":"A","explanation":"many rules→宾格 **them**(作 follow 的宾语)。"},{"q":"2","options":["to","at","in","for"],"answer":"D","explanation":"be late **for** school(固定搭配:……迟到)。"},{"q":"3","options":["uniform","uniforms","shoe","clothes"],"answer":"B","explanation":"our school **uniforms**(校服,用复数)。"},{"q":"4","options":["brings","to bring","bring","bringing"],"answer":"C","explanation":"情态动词 Can 后接动词原形→**bring**。"},{"q":"5","options":["Not","No","Can''t","Don''t"],"answer":"D","explanation":"否定祈使句:**Don’t**+动词原形 run。"},{"q":"6","options":["walk","walks","walking","to walk"],"answer":"A","explanation":"情态动词 must 后接动词原形→**walk**。"},{"q":"7","options":["must","can","have","should"],"answer":"C","explanation":"后面有 to→**have** to do sth(必须;must/can 后不加 to)。"},{"q":"8","options":["we","us","our","ours"],"answer":"B","explanation":"Let **us**+动词原形(祈使句固定,用宾格)。"}]'::jsonb, 1
WHERE NOT EXISTS (SELECT 1 FROM junior_cloze WHERE title = '七下 U2 完形:Our School Rules');

INSERT INTO junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order)
SELECT 'c2000002-0a1b-4c2d-8e3f-000000000004', 7, '7B', 'U2', '七下 U2 完形:Rules in the Library', 'The city library is a wonderful place. It is very (1)____ inside, so many people love to read books here. But we must follow the library rules. When you enter the library, please don''t (2)____ or make noise. Your mobile phones (3)____ be off, or you can put them on silent mode. Can we (4)____ juices or water here? Yes, but you must be careful. Do not drop water on the books. (5)____ clean after you drink. Also, we can (6)____ three books from the library every time. But we cannot keep them (7)____ a long time. Let''s remember these (8)____ and enjoy our reading time.', 106, 2, '[{"q":"1","options":["noisy","dirty","cold","quiet"],"answer":"D","explanation":"图书馆很 **quiet**(安静),后文 make noise 印证。"},{"q":"2","options":["read","sit","talk","look"],"answer":"C","explanation":"don’t **talk** or make noise(说话会产生噪音)。"},{"q":"3","options":["can","must","have","mustn''t"],"answer":"B","explanation":"手机 **must** be off(规定:必须关)。"},{"q":"4","options":["drink","wash","buy","sell"],"answer":"A","explanation":"**drink** juices or water(喝),后文 after you drink。"},{"q":"5","options":["Leave","Make","Keep","Give"],"answer":"C","explanation":"**Keep** clean=保持干净(Keep+形容词)。"},{"q":"6","options":["borrow","lose","write","buy"],"answer":"A","explanation":"**borrow** … from the library(借书)。"},{"q":"7","options":["in","at","on","for"],"answer":"D","explanation":"cannot keep them **for** a long time(for+一段时间)。"},{"q":"8","options":["plans","rules","stories","games"],"answer":"B","explanation":"remember these **rules**(规则,全文主题)。"}]'::jsonb, 2
WHERE NOT EXISTS (SELECT 1 FROM junior_cloze WHERE title = '七下 U2 完形:Rules in the Library');

-- 校验(单独跑): U1/U2 应共 4 行, blanks 各 8
SELECT unit, title, word_count, jsonb_array_length(questions) AS blanks FROM junior_cloze WHERE volume='7B' AND unit IN ('U1','U2') ORDER BY unit, sort_order;
-- END OF FILE cloze-u1u2.sql
